komponenten-inputs-forms-slider.apiDescription:
## Inputs

```
export type SliderComponentInputs = {
  /**
   * Markenbereich → .slider-<area> (Thumb- + Output-Farbe).
   *
   * @default co
   */
  area?: CdsArea;
  /**
   * Deaktiviert; auch über Angular-Forms (setDisabledState) steuerbar.
   *
   * @default false
   */
  disabled?: boolean; // two-way: [(disabled)]
  /** @default Schritte: 5.000 € */
  helper?: string;
  /** @default Budget-Rahmen */
  label?: string;
  /** @default 100000 */
  max?: number;
  /** @default 10000 */
  min?: number;
  /**
   * Mindestbreite (px) pro Tick-Label, ab der reduziert wird.
   *
   * @default 56
   */
  minTickSpacing?: number;
  sliderId?: string;
  /** @default 5000 */
  step?: number;
  /**
   * Gewünschte Anzahl Ticks (inkl. Endpunkte). 0 = keine. Wird bei zu schmalem
   *  Slider automatisch reduziert.
   *
   * @default 3
   */
  tickCount?: number;
  /**
   * Einheit, an den formatierten Wert angehängt (z. B. ' €').
   *
   * @default  €
   */
  unit?: string;
  /**
   * Aktueller Wert. Two-Way (`[(value)]`) UND Angular-Forms.
   *
   * @default 50000
   */
  value?: number; // two-way: [(value)]
}
```

## Outputs

```
export type SliderComponentOutputs = {
  /** Deaktiviert; auch über Angular-Forms (setDisabledState) steuerbar. */
  disabledChange: (e: boolean) => void;
  /** Aktueller Wert. Two-Way (`[(value)]`) UND Angular-Forms. */
  valueChange: (e: number) => void;
}
```
